for s,(name,items) in enumerate(sections):
 for i,item in enumerate(items):
  label,typ=item.split('|');q={'id':f'S{s+1:02}Q{i+1:02}','section':s,'label':label.rstrip('*'),'required':label.endswith('*'),'type':'text','options':[]}
