  if s==8 and 7<=i<=9:q['when']=['S09Q01','クライアントが写真を提供']
  if s==8 and i==11:q['when']=['S09Q01','リアルなAI画像生成']
  if s==9 and i>0:q['unless']=['S10Q01','映像は不要']
  if s==7 and i>0:q['when']=['S08Q01','あり']
  qs.append(q)
